{"args":["-lc","node -e '
const fs=require("fs");
let txt=fs.readFileSync("/tmp/m1/image.ppm","utf8");
let parts=txt.trim().split(/\s+/);
let w=800,h=600;
let pix=[];
for(let i=4;i<parts.length;i+=3) pix.push([+parts[i],+parts[i+1],+parts[i+2]]);
function px(x,y){return pix[y*w+x];}
// dump small ascii preview: map colors to chars
// sky = blue-ish (b=255), ground checker? 152 gray vs 67 gray checker, red sphere 51,10,10?
// lets find bounding box of red sphere
let minx=1e9,maxx=-1,minY=1e9,maxY=-1;
for(let y=0;y<h;y++)for(let x=0;x<w;x++){let p=px(x,y); if(p[0]==51&&p[1]==10&&p[2]==10){if(x<minx)minx=x; if(x>maxx)maxx=x; if(y<minY)minY=y; if(y>maxY)maxY=y;}}
console.log("red bbox",minx,maxx,minY,maxY);
// other dark colors?
let uniq=[...new Set(pix.map(p=>p.join(",")))];
console.log(uniq.filter(s=>s.startsWith("51")||s.startsWith("20")||s.startsWith("46")).slice(0,30));
// check vertical gradient: col 400? top is sky, center red, bottom checker
for(let y=0;y<h;y+=50) console.log(y, px(400,y).join(","));
for(let y=0;y<h;y+=50) console.log("x100 y"+y, px(100,y).join(","));
// shadow? check checker pattern at bottom
for(let y=350;y<600;y+=30){let row=""; for(let x=0;x<w;x+=40){let p=px(x,y); let c=(p[0]>100&&p[2]==255)?".":(p[0]==152?"L":(p[0]==67?"D":(p[0]==51?"R":"?"))); row+=c;} console.log(y+" "+row);}
'
"],"command":"bash","cwd":"/app"}

